"""Storage keys -> paths under DATA_DIR. Keys are generated by the API; anything else is rejected."""

import os
import re
from pathlib import Path

_SEGMENT = re.compile(r"^[A-Za-z0-9._-]+$")


def data_dir() -> Path:
    return Path(os.environ.get("DATA_DIR", "/data")).resolve()


def resolve_key(key: str) -> Path:
    parts = key.split("/")
    if not key or any(p in ("", ".", "..") or not _SEGMENT.match(p) for p in parts):
        raise ValueError(f"invalid storage key: {key!r}")
    root = data_dir()
    path = root.joinpath(*parts).resolve()
    if not path.is_relative_to(root):
        raise ValueError(f"invalid storage key: {key!r}")
    return path


def key_of(path: Path) -> str:
    return path.resolve().relative_to(data_dir()).as_posix()
